// Bundles the frozen system prompts into the server (PLAN §4.5). The Next.js bundle cannot read
// packages/agent/prompts/*.md from disk at runtime, so this writes them into
// packages/agent/src/prompts.generated.ts as string constants with a sha256 each.
//
//   pnpm prompts:build
//
// build-prompts.test.ts fails while the generated file is out of date with the Markdown sources.
import { createHash } from "node:crypto";
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { approxTokens } from "@ct/contracts";

const ROOT = fileURLToPath(new URL("../..", import.meta.url));
export const PROMPTS_DIR = path.join(ROOT, "packages", "agent", "prompts");
export const GENERATED_FILE = path.join(ROOT, "packages", "agent", "src", "prompts.generated.ts");

export interface PromptSource {
  /** File stem, e.g. "director"; the key in PROMPT_HASHES. */
  name: string;
  /** The exported constant, e.g. DIRECTOR_PROMPT. */
  constant: string;
  /** Normalised text: what the model receives. */
  text: string;
  sha256: string;
}

/**
 * The text as the model receives it: no BOM, LF line endings, no trailing whitespace at the end.
 * A Windows checkout (CRLF) and a Linux one therefore produce the same constant and the same hash.
 */
export function normalizePrompt(raw: string): string {
  return raw.replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").trimEnd();
}

export function sha256(text: string): string {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

/** director.md → DIRECTOR_PROMPT. */
export function constantName(stem: string): string {
  return `${stem.toUpperCase().replace(/[^A-Z0-9]+/g, "_")}_PROMPT`;
}

/** Every prompts/*.md file, sorted by name so the output is stable. */
export function readPromptSources(dir: string = PROMPTS_DIR): PromptSource[] {
  return readdirSync(dir)
    .filter((f) => f.endsWith(".md"))
    .sort()
    .map((file) => {
      const name = file.slice(0, -".md".length);
      if (!/^[a-z][a-z0-9_-]*$/.test(name)) throw new Error(`prompt file name must be lower-case: ${file}`);
      const text = normalizePrompt(readFileSync(path.join(dir, file), "utf8"));
      if (text === "") throw new Error(`prompt file is empty: ${file}`);
      return { name, constant: constantName(name), text, sha256: sha256(text) };
    });
}

/**
 * Escapes text for a template literal. Template literals keep the prompt readable in the generated
 * file, and the language normalises CRLF inside them to LF, so a CRLF checkout of the generated file
 * still yields the hashed text.
 */
export function escapeTemplate(text: string): string {
  return text.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
}

/** The generated module's source for these prompts. */
export function renderPromptsModule(sources: readonly PromptSource[]): string {
  const constants = sources.map(
    (s) => `/** packages/agent/prompts/${s.name}.md */\nexport const ${s.constant} = \`${escapeTemplate(s.text)}\`;\n`,
  );
  const key = (name: string) => (/^[a-z_][a-z0-9_]*$/.test(name) ? name : JSON.stringify(name));
  const hashType = sources.map((s) => `${key(s.name)}: string`).join("; ");
  const hashes = sources.map((s) => `  ${key(s.name)}: ${JSON.stringify(s.sha256)},`).join("\n");
  return [
    "// Generated by tools/dev/build-prompts.ts from packages/agent/prompts/*.md: do not edit.",
    "// Edit the Markdown and run `pnpm prompts:build`; tools/dev/build-prompts.test.ts fails while this file is stale.",
    "",
    ...constants,
    "/** sha256 of each prompt exactly as embedded above, keyed by file name. */",
    `export const PROMPT_HASHES: Readonly<{ ${hashType} }> = {`,
    hashes,
    "};",
    "",
  ].join("\n");
}

/** The generated file as committed, with line endings normalised for comparison. */
export function readGeneratedFile(file: string = GENERATED_FILE): string {
  return readFileSync(file, "utf8").replace(/\r\n?/g, "\n");
}

function main(): void {
  const sources = readPromptSources();
  writeFileSync(GENERATED_FILE, renderPromptsModule(sources), "utf8");
  for (const s of sources) {
    console.log(`${s.constant.padEnd(18)} ~${approxTokens(s.text)} tokens  sha256 ${s.sha256.slice(0, 12)}`);
  }
  console.log(`wrote ${path.relative(ROOT, GENERATED_FILE).split(path.sep).join("/")}`);
}

if (path.basename(process.argv[1] ?? "") === "build-prompts.ts") main();
